const IDLE_POLL_MS = 200;

const db: DatabaseSync = openDatabase();
let stopping = false;

function heartbeat(): void {
  run(
    db,
    `INSERT INTO worker_heartbeat (id, pid, seen_at) VALUES (1, ?, ?)
     ON CONFLICT (id) DO UPDATE SET pid = excluded.pid, seen_at = excluded.seen_at`,
    process.pid,
    Date.now(),
  );
}

